type ImagePageReply = { quote: RecordWithImages; uploadedIndexes: number[]; complete: boolean; total: number };
export function quoteImagesComplete(record: RecordWithImages | null): boolean {
  return !!record && (record.imageUpload ? record.imageUpload.complete : !!record.images?.length);
}
export async function archiveQuoteImagePages(record: RecordWithImages, images: string[], upload: (body: { index: number; total: number; image: string }) => Promise<ImagePageReply>, onProgress?: (record: RecordWithImages) => void): Promise<RecordWithImages> {
  if (quoteImagesComplete(record)) return record;
  if (!images.length || images.length > 30) throw new Error("报价原图页数须为1至30页");
  if (record.imageUpload && record.imageUpload.total !== images.length) throw new Error("当前生成页数与已开始存档的原图页数不同，不能混合保存。请联系管理员核对。");
  const received = new Set(record.imageUpload?.uploadedIndexes || []);
  let latest = record;
  for (let index = 0; index < images.length; index++) {
    if (received.has(index)) continue;
    const result = await upload({ index, total: images.length, image: images[index] });
    if (result.quote.id !== record.id || result.total !== images.length || !result.uploadedIndexes.includes(index)) throw new Error("主机返回的原图存档进度不一致，请重新读取报价后续存。");
    result.uploadedIndexes.forEach(value => received.add(value)); latest = result.quote;
    onProgress?.(latest);
  }
  if (!quoteImagesComplete(latest) || latest.images?.length !== images.length) throw new Error("报价原图尚未全部存档，请重新读取进度后补存。");
  return latest;
}
type ImageFileResult = { ok: boolean; path?: string; canceled?: boolean; error?: string };
type ImageFileBridge = Window["jewelryDesktop"] & { shareImage?: (input: { src: string; name: string }) => Promise<ImageFileResult>; saveImageAs?: (input: { src: string; name: string }) => Promise<ImageFileResult>; getImageSaveSettings?: () => Promise<{ path: string }>; chooseImageSaveFolder?: () => Promise<ImageFileResult> };
