export async function saveQuoteImageBatch(images: string[], name: string, save: (input: { src: string; name: string }) => Promise<ImageFileResult>) {
  const paths: string[] = [];
  for (let index = 0; index < images.length; index++) {
    const result = await save({ src: images[index], name: `${name}-${index + 1}.png` });
    if (result.canceled) return { savedCount: index, canceled: true, paths };
    if (!result.ok) throw new Error(`已保存 ${index} 张，第 ${index + 1} 张未保存：${result.error || "请重试"}`);
    if (result.path) paths.push(result.path);
  }
  return { savedCount: images.length, canceled: false, paths };
}
