  if (file.size > 1_125_000) throw new Error("确认截图单张约限1MB，请选择较小的原文件，程序不会压缩归档截图。");
  const image = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error("确认截图读取失败，请重选文件。")); reader.readAsDataURL(file); });
