      const result = await api<{ quote: RecordWithImages }>("/api/quotes", "POST", payload); record = result.quote; setSaved(record); setDrafts(current => ({ ...current, [draft.type]: { ...(record!.data || record!.snapshot), customerBrief: record!.snapshot.customer?.id === record!.customerId ? { id: record!.snapshot.customer.id, name: record!.snapshot.customer.name, phone: record!.snapshot.customer.phone } : undefined, images: [], baseQuoteId: record!.id } }));
